<template>
  <v-card class="table">
    <v-data-table
      :headers="headers"
      :items="tournaments"
      :search="search"
      :custom-filter="tournamentFilter"
      :items-per-page="-1"
      hide-default-footer
      :mobile-breakpoint="0"
      multi-sort
      data-cy="TournamentsList"
    >
      <template v-slot:top>
        <v-card-title>
          <v-text-field
            v-model="search"
            append-icon="search"
            label="Search"
            class="mx-2"
          />
          <v-spacer />
          <v-btn
            color="primary"
            class="text-white"
            @click="newTournament"
            data-cy="createButton"
            >New Tournament
          </v-btn>
        </v-card-title>
      </template>

      <template v-slot:[`item.actions`]="{ item }">
        <div class="tournament-actions">
        <v-tooltip location="bottom" v-if="((item as any).raw || item).canChange()">
          <template v-slot:activator="{ props: activatorProps }">
            <span data-cy="EditTournament" v-bind="activatorProps" @click="editTournament((item as any).raw || item)">
              <v-icon
                size="large"
                class="mr-2"
                >create</v-icon
              >
            </span>
          </template>
          <span>Edit Tournament</span>
        </v-tooltip>

        <v-tooltip location="bottom" v-if="((item as any).raw || item).canJoinPublic()">
          <template v-slot:activator="{ props: activatorProps }">
            <span data-cy="JoinTournament" v-bind="activatorProps" @click="joinPublicTournament((item as any).raw || item)">
              <v-icon
                size="large"
                class="mr-2"
                >fa-sign-in-alt</v-icon
              >
            </span>
          </template>
          <span>Join Tournament</span>
        </v-tooltip>
        <v-tooltip location="bottom" v-if="((item as any).raw || item).canJoinPrivate()">
          <template v-slot:activator="{ props: activatorProps }">
            <span data-cy="JoinTournament" v-bind="activatorProps" @click="openPasswordDialog((item as any).raw || item)">
              <v-icon
                size="large"
                class="mr-2"
                >fa-sign-in-alt</v-icon
              >
            </span>
          </template>
          <span>Join Tournament</span>
        </v-tooltip>
        <v-tooltip location="bottom" v-if="((item as any).raw || item).canLeave()">
          <template v-slot:activator="{ props: activatorProps }">
            <span data-cy="LeaveTournament" v-bind="activatorProps" @click="leaveTournament((item as any).raw || item)">
              <v-icon
                size="large"
                class="mr-2"
                >fas fa-sign-out-alt</v-icon
              >
            </span>
          </template>
          <span>Leave Tournament</span>
        </v-tooltip>
        <v-tooltip location="bottom" v-if="((item as any).raw || item).canSolveQuiz()">
          <template v-slot:activator="{ props: activatorProps }">
            <span data-cy="SolveQuiz" v-bind="activatorProps" @click="solveQuiz((item as any).raw || item)">
              <v-icon
                size="large"
                class="mr-2"
                >fa-file-signature</v-icon
              >
            </span>
          </template>
          <span>Solve Quiz</span>
        </v-tooltip>
        <v-tooltip location="bottom" v-if="((item as any).raw || item).canSeeResults()">
          <template v-slot:activator="{ props: activatorProps }">
            <span data-cy="SeeSolvedQuiz" v-bind="activatorProps" @click="openSolvedQuiz()">
              <v-icon
                size="large"
                class="mr-2"
                >fas fa-file-alt</v-icon
              >
            </span>
          </template>
          <span>See Solved Quiz</span>
        </v-tooltip>

        <v-tooltip location="bottom" v-if="((item as any).raw || item).canChange()">
          <template v-slot:activator="{ props: activatorProps }">
            <span data-cy="CancelTournament" v-bind="activatorProps" @click="cancelTournament((item as any).raw || item)">
              <v-icon
                size="large"
                class="mr-2"
                >cancel</v-icon
              >
            </span>
          </template>
          <span>Cancel Tournament</span>
        </v-tooltip>
        <v-tooltip location="bottom" v-if="((item as any).raw || item).canChange()">
          <template v-slot:activator="{ props: activatorProps }">
            <span data-cy="RemoveTournament" v-bind="activatorProps" @click="removeTournament((item as any).raw || item)">
              <v-icon
                size="large"
                class="mr-2"
                color="red"
                >delete</v-icon
              >
            </span>
          </template>
          <span>Remove Tournament</span>
        </v-tooltip>
        </div>
      </template>

      <template v-slot:[`item.id`]="{ item }">
        <v-chip color="primary" class="text-white" size="small" @click="openTournamentDashboard((item as any).raw || item)">
          <span> {{ ((item as any).raw || item).id }} </span>
        </v-chip>
      </template>

      <template v-slot:[`item.creator`]="{ item }">
        <v-chip size="small">
          <span> {{ ((item as any).raw || item).creator.name }} </span>
        </v-chip>
      </template>

      <template v-slot:[`item.topics`]="{ item }">
        <view-tournament-topics :tournament="(item as any).raw || item" />
      </template>

      <template v-slot:[`item.state`]="{ item }">
        <v-chip :color="((item as any).raw || item).getStateColor()">
          {{ ((item as any).raw || item).getStateName() }}
        </v-chip>
      </template>

      <template v-slot:[`item.privateTournament`]="{ item }">
        <v-chip :color="((item as any).raw || item).getPrivateColor()">
          {{ ((item as any).raw || item).getPrivateName() }}
        </v-chip>
      </template>

      <template v-slot:[`item.times`]="{ item }">
        <div class="tournament-times">
          <v-chip size="x-small">
            {{ ((item as any).raw || item).startTime }}
          </v-chip>
          <v-chip size="x-small">
            {{ ((item as any).raw || item).endTime }}
          </v-chip>
        </div>
      </template>

      <template v-slot:[`item.enrolled`]="{ item }">
        <v-chip :color="((item as any).raw || item).getEnrolledColor()">
          {{ ((item as any).raw || item).getEnrolledName() }}
        </v-chip>
      </template>
    </v-data-table>
    <footer>
      Press <v-icon class="mr-2">fas fa-file-alt</v-icon> to see tournament quiz
      answers. <v-icon class="mr-2">mouse</v-icon>Left-click on tournament's
      number to view the current ranking.
    </footer>
    <tournament-dialog
      v-if="currentTournament && createTournamentDialog"
      v-model:dialog="createTournamentDialog"
      :tournament="currentTournament"
      :edit-mode="false"
      @new-tournament="onCreateTournament"
      @close-dialog="onCloseDialog"
    />
    <edit-password-dialog
      v-if="currentTournament && editPasswordDialog"
      v-model:dialog="editPasswordDialog"
      :tournament="currentTournament"
      @enter-password="joinPrivateTournament"
      @close-password-dialog="onClosePasswordDialog"
    />
    <tournament-dialog
      v-if="currentTournament && editTournamentDialog"
      v-model:dialog="editTournamentDialog"
      :tournament="currentTournament"
      :edit-mode="true"
      @edit-tournament="onEditTournament"
      @close-edit-dialog="onCloseEditDialog"
    />
  </v-card>
</template>

<script setup lang="ts">
import { withV2ColumnWidths } from '@/services/DataTableHeaders';
import { ref, watch, onMounted } from 'vue';
import { useStore } from '@/store';
import { useRouter } from 'vue-router';
import RemoteServices from '@/services/RemoteServices';
import TournamentDialog from '@/views/student/tournament/TournamentForm.vue';
import EditPasswordDialog from '@/views/student/tournament/PasswordTournamentView.vue';
import ViewTournamentTopics from '@/views/student/tournament/ViewTournamentTopics.vue';
import Tournament from '@/models/user/Tournament';
import StatementQuiz from '@/models/statement/StatementQuiz';

const props = defineProps<{ type: string }>();

const emit = defineEmits(['close-show-dashboard-dialog']);

const store = useStore();
const router = useRouter();

const tournaments = ref<Tournament[]>([]);
const currentTournament = ref<Tournament | null>(null);
const createTournamentDialog = ref(false);
const editPasswordDialog = ref(false);
const editTournamentDialog = ref(false);
const search = ref('');
const password = ref('');
const tournamentFilter = (_value: unknown, query: string, item?: unknown) =>
  Tournament.matchesSearch(item, query);
const headers: any = withV2ColumnWidths([
  {
    title: 'Actions',
    key: 'actions',
    align: 'center',
    sortable: false,
    minWidth: '200px',
  },
  {
    title: 'Tournament Number',
    key: 'id',
    align: 'center',
    width: '10%',
  },
  {
    title: 'Creator',
    key: 'creator',
    align: 'center',
    width: '10%',
  },
  {
    title: 'Topics',
    key: 'topics',
    align: 'center',
    width: '10%',
  },
  {
    title: 'State',
    key: 'state',
    align: 'center',
    width: '10%',
  },
  {
    title: 'Privacy',
    key: 'privateTournament',
    align: 'center',
    width: '10%',
  },
  {
    title: 'Start/End Time',
    key: 'times',
    align: 'center',
    width: '10%',
  },
  {
    title: 'Number of Questions',
    key: 'numberOfQuestions',
    align: 'center',
    width: '10%',
  },
  {
    title: 'Enrolled',
    key: 'enrolled',
    align: 'center',
    width: '10%',
  },
]);

const getTournamentsList = async () => {
  store.setLoading();
  try {
    if (props.type === 'OPEN') {
      tournaments.value = await RemoteServices.getOpenedTournamentsForCourseExecution();
    } else {
      tournaments.value = await RemoteServices.getClosedTournamentsForCourseExecution();
    }
    tournaments.value.sort((a, b) => Tournament.sortById(a, b));
  } catch (error) {
    store.setError(error as string);
  }
  store.clearLoading();
};

onMounted(() => {
  getTournamentsList();
});

watch(() => props.type, () => {
  getTournamentsList();
});

const openTournamentDashboard = async (tournament: Tournament) => {
  emit('close-show-dashboard-dialog', false);
  if (tournament) {
    await router.push({
      path: '/student/tournament',
      query: { id: tournament.id.toString() },
    });
  }
};


const openSolvedQuiz = async () => {
  await router.push({ name: 'solved-quizzes' });
};

const newTournament = () => {
  currentTournament.value = new Tournament();
  createTournamentDialog.value = true;
};

const onCreateTournament = async (tournament: Tournament) => {
  tournaments.value.unshift(tournament);
  createTournamentDialog.value = false;
  currentTournament.value = null;
};

const onCloseDialog = () => {
  createTournamentDialog.value = false;
  currentTournament.value = null;
};

const openPasswordDialog = (tournamentToJoin: Tournament) => {
  currentTournament.value = tournamentToJoin;
  editPasswordDialog.value = true;
};

const onClosePasswordDialog = () => {
  editPasswordDialog.value = false;
  currentTournament.value = null;
};

const onEditTournament = async (tournament: Tournament) => {
  currentTournament.value = tournament;
  try {
    tournaments.value = await RemoteServices.getTournamentsForCourseExecution();
  } catch (error) {
    store.setError(error as string);
  }
  editTournamentDialog.value = false;
  currentTournament.value = null;
};

const onCloseEditDialog = () => {
  editTournamentDialog.value = false;
  currentTournament.value = null;
};

const editTournament = (tournamentToEdit: Tournament) => {
  currentTournament.value = tournamentToEdit;
  editTournamentDialog.value = true;
};

const joinPrivateTournament = async (pwd: string) => {
  password.value = pwd;
  if (currentTournament.value) {
    await joinPublicTournament(currentTournament.value);
  }
  editPasswordDialog.value = false;
  currentTournament.value = null;
  password.value = '';
};

const joinPublicTournament = async (tournamentToJoin: Tournament) => {
  try {
    await RemoteServices.joinTournament(tournamentToJoin.id, password.value);
    tournamentToJoin.enrolled = true;
  } catch (error) {
    store.setError(error as string);
    return;
  }
};

const leaveTournament = async (tournamentToLeave: Tournament) => {
  try {
    await RemoteServices.leaveTournament(tournamentToLeave.id);
    tournamentToLeave.enrolled = false;
  } catch (error) {
    store.setError(error as string);
    return;
  }
};

const solveQuiz = async (tournament: Tournament) => {
  store.setLoading();

  let statementQuiz: StatementQuiz;
  try {
    statementQuiz = await RemoteServices.solveTournament(tournament.id);
    await store.setStatementQuiz(statementQuiz);
    await router.push({ name: 'solve-quiz' });
  } catch (error) {
    store.setError(error as string);
  }

  store.clearLoading();
};

const cancelTournament = async (tournamentToCancel: Tournament) => {
  if (confirm('Are you sure you want to cancel this tournament?')) {
    try {
      await RemoteServices.cancelTournament(tournamentToCancel.id);
      tournamentToCancel.canceled = true;
    } catch (error) {
      store.setError(error as string);
      return;
    }
  }
};

const removeTournament = async (tournamentToRemove: Tournament) => {
  if (confirm('Are you sure you want to delete this tournament?')) {
    try {
      if (tournamentToRemove.id) {
        await RemoteServices.removeTournament(tournamentToRemove.id);
      }
      tournaments.value = tournaments.value.filter(
        (tournament) => tournament.id !== tournamentToRemove.id
      );
    } catch (error) {
      store.setError(error as string);
      return;
    }
  }
};
</script>

<style lang="scss" scoped>
.tournament-actions {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: center;
  gap: 4px;

  span {
    cursor: pointer;
  }
}

.tournament-times {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}
</style>
