import { ISOtoString } from '@/services/ConvertDateService';

export default class Review {
  id!: number;
  userId: number | null = null;
  questionSubmissionId: number | null = null;
  questionGenerationId: number | null = null;
  comment!: string;
  type!: string;
  creationDate!: string;
  name!: string;
  username!: string;

  static statusOptions = [
    { title: 'Comment', key: 'COMMENT' },
    { title: 'Request Changes', key: 'REQUEST_CHANGES', color: 'yellow' },
    { title: 'Approve', key: 'APPROVE', color: 'green' },
    { title: 'Reject', key: 'REJECT', color: 'red' },
  ];

  // The option shown for a review-type select item. Vuetify 4's `selection` slot hands over the
  // option itself (`{ title, key, color }`), older ones a wrapper with `raw` or `value`; a plain key works too
  static statusOptionFor(item: any): { title: string; key: string; color?: string } {
    const value = item?.key ?? item?.raw?.key ?? item?.value ?? item;
    return Review.statusOptions.find((option) => option.key === value) ?? { title: String(value ?? ''), key: value };
  }

  constructor(jsonObj?: Review) {
    if (jsonObj) {
      this.id = jsonObj.id;
      this.userId = jsonObj.userId;
      this.questionSubmissionId = jsonObj.questionSubmissionId;
      this.questionGenerationId = jsonObj.questionGenerationId;
      this.comment = jsonObj.comment;
      this.type = jsonObj.type;
      this.creationDate = ISOtoString(jsonObj.creationDate);
      this.name = jsonObj.name;
      this.username = jsonObj.username;
    }
  }

  prepareReview(
    questionSubmissionId: number,
    type: string,
    comment: string,
    userId: number
  ) {
    this.questionSubmissionId = questionSubmissionId;
    this.type = type;
    this.userId = userId;
    this.comment = comment;
  }

  prepareGenerationReview(
    questionGenerationId: number,
    type: string,
    comment: string,
    userId: number
  ) {
    this.questionGenerationId = questionGenerationId;
    this.type = type;
    this.userId = userId;
    this.comment = comment;
  }

  getStatusColor() {
    switch (this.type) {
      case 'APPROVE':
        return 'green';
      case 'REJECT':
        return 'red';
      case 'REQUEST_CHANGES':
        return 'yellow';
      case 'REQUEST_REVIEW':
        return 'blue';
    }
  }

  getType(firstReview: boolean) {
    switch (this.type) {
      case 'APPROVE':
        return 'APPROVED';
      case 'REJECT':
        return 'REJECTED';
      case 'REQUEST_CHANGES':
        return 'CHANGES REQUESTED';
      case 'REQUEST_REVIEW':
        return firstReview ? 'NEW SUBMISSION' : 'SUBMISSION EDITED';
    }
  }

  isComment() {
    return this.type === 'COMMENT';
  }

  isUsersReview(username: string) {
    return username === this.username;
  }
}
