<template>
  <v-expansion-panels v-if="discussion.replies.length > 0" variant="inset">
    <v-expansion-panel>
      <v-expansion-panel-title style="background-color: #d5d5d5"
        >Show replies
      </v-expansion-panel-title>
      <v-expansion-panel-text>
        <div
          v-for="reply in discussion.replies"
          :key="reply.id"
          class="text-left reply"
        >
          <div v-if="user?.role === 'STUDENT'" style="width: 100%">
            <div>
              <b v-if="user?.id !== reply.userId"
                >{{ reply.name }} ({{ reply.username }}) replied on
                {{ reply.date }} :
              </b>
              <b v-else>You replied on {{ reply.date }} :</b>
              <span v-html="convertMarkDownText(reply.message)" />
            </div>
          </div>
          <div v-else style="display: inline-flex; width: 100%">
            <div style="width: 88%">
              <b v-if="user?.id !== reply.userId"
                >{{ reply.name }} ({{ reply.username }}) replied on
                {{ reply.date }}:
              </b>
              <b v-else>You replied on {{ reply.date }} :</b>
              <span v-html="convertMarkDownText(reply.message)" />
            </div>
            <v-switch
              style="width: 12%"
              v-model="reply.public"
              :label="reply.public ? 'Public' : 'Private'"
              @change="changeReplyAvailability(reply.id)"
            />
          </div>
        </div>
        <div class="reply-message" v-if="!discussion.closed">
          <v-textarea
            data-cy="replyTextArea"
            class="textarea-reply"
            variant="solo"
            :id="'reply' + discussion.id"
            label="Type a reply..."
            :model-value="replyMessage"
            @update:model-value="setReplyMessage"
          ></v-textarea>
          <v-card-actions>
            <v-btn
              v-if="canSuggest"
              data-cy="suggestReplyButton"
              variant="text"
              :loading="suggesting"
              @click="suggestReply"
              >Suggest reply</v-btn
            >
            <v-btn
              data-cy="submitReplyButton"
              class="submit-button"
              @click="
                submitReply();
                clearTextarea('#reply' + discussion.id);
              "
              >Submit</v-btn
            >
          </v-card-actions>
        </div>
      </v-expansion-panel-text>
    </v-expansion-panel>
  </v-expansion-panels>
  <div v-else class="reply-message">
    <v-textarea
      data-cy="replyTextArea"
      class="textarea-reply"
      variant="solo"
      :id="'reply' + discussion.id"
      label="Type a reply..."
      :model-value="replyMessage"
      @update:model-value="setReplyMessage"
    ></v-textarea>
    <v-card-actions>
      <v-btn
        v-if="canSuggest"
        data-cy="suggestReplyButton"
        variant="text"
        :loading="suggesting"
        @click="suggestReply"
        >Suggest reply</v-btn
      >
      <v-btn
        data-cy="submitReplyButton"
        class="submit-button"
        @click="
          submitReply();
          clearTextarea('#reply' + discussion.id);
        "
        >Submit</v-btn
      >
    </v-card-actions>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue';
import { useStore } from '@/store';
import { convertMarkDown } from '@/services/ConvertMarkdownService';
import Discussion from '@/models/management/Discussion';
import RemoteServices from '../../../services/RemoteServices';
import User from '@/models/user/User';
import Reply from '@/models/management/Reply';

const props = defineProps<{
  discussion: Discussion;
}>();

const store = useStore();
const replyMessage = ref('');
const user = store.user as User | null;
const canSuggest = store.canGenerateQuestions;
const suggesting = ref(false);

// Fills the box with a draft for the teacher to read and fix; it is never sent by itself
const suggestReply = async () => {
  if (replyMessage.value.trim() !== '' && !confirm('Replace what you wrote with a suggested reply?')) return;
  suggesting.value = true;
  try {
    const suggestion = await RemoteServices.suggestReply(props.discussion.id);
    replyMessage.value = suggestion.reply;
  } catch (error) {
    store.setError(error as string);
  }
  suggesting.value = false;
};

const submitReply = async () => {
  if (replyMessage.value.trim() === '') {
    store.setError('Reply must have content');
    return;
  }

  let reply = new Reply();
  reply.message = replyMessage.value;
  reply.username = user?.username ?? '';
  reply.date = new Date().toISOString();

  try {
    let replyResponse = await RemoteServices.addReply(
      reply,
      props.discussion.id
    );

    if (props.discussion.replies === null) {
      props.discussion.replies = [];
    }
    props.discussion.replies.push(replyResponse);
    props.discussion.lastReplyDate = replyResponse.date;

    replyMessage.value = '';
  } catch (error) {
    store.setError(error as string);
  }
};

const setReplyMessage = (message: string) => {
  replyMessage.value = message;
};

const convertMarkDownText = (text: string) => {
  return convertMarkDown(text, null);
};

const clearTextarea = (name: string) => {
  let textArea = document.querySelector(name);
  if (textArea) {
    (textArea as HTMLTextAreaElement).value = ' ';
  }
};

const changeReplyAvailability = async (id: number) => {
  store.setLoading();
  try {
    await RemoteServices.changeReplyAvailability(id);
  } catch (error) {
    store.setError(error as string);
  }
  store.clearLoading();
};
</script>
