// Layer order is fixed in index.html, so this import can live anywhere
import '@/assets/css/_v2-reset.scss';
import '@fortawesome/fontawesome-free/css/all.css';
import '@mdi/font/css/materialdesignicons.css';
import 'material-design-icons-iconfont/dist/material-design-icons.css';
import 'vuetify/styles';
import { createVuetify } from 'vuetify';
import * as components from 'vuetify/components';
import * as directives from 'vuetify/directives';
import { aliases } from 'vuetify/iconsets/mdi';

import { h } from 'vue';
import type { IconSet, IconProps } from 'vuetify';

const custom: IconSet = {
  component: (props: IconProps) => {
    const icon = props.icon as string;
    if (typeof icon !== 'string') return h(props.tag);

    if (icon.startsWith('fa') && icon.includes('-')) {
      // Font Awesome 6+ only draws the glyph when a style class (fas/far/fab) is present
      const hasStyle = /^(fa[srbld]|fa-(solid|regular|brands|light|duotone))\b/.test(icon);
      return h(props.tag, { class: hasStyle ? [icon] : ['fas', icon] });
    } else if (icon.startsWith('mdi-')) {
      return h(props.tag, { class: ['mdi', icon] });
    } else {
      return h(props.tag, { class: ['material-icons'] }, icon);
    }
  },
};

export default createVuetify({
  components,
  directives,
  defaults: {
    VAppBar: {
      height: 64,
      elevation: 4,
    },
    VBtn: {
      variant: 'elevated',
      style: 'text-transform: uppercase; letter-spacing: 0.0892857143em;',
    },
    VCardActions: {
      VBtn: {
        variant: 'elevated',
      },
    },
    // persistentCounter: V2 showed a `counter` even when the field was not focused
    VTextField: {
      variant: 'underlined',
      persistentCounter: true,
    },
    VTextarea: {
      variant: 'underlined',
      persistentCounter: true,
    },
    VAutocomplete: {
      variant: 'underlined',
    },
    VCombobox: {
      variant: 'underlined',
    },
    VSelect: {
      variant: 'underlined',
    },
    VList: {
      density: 'compact',
    },
    // V2 chips were filled with their colour; V4 defaults to a light tonal tint
    VChip: {
      variant: 'flat',
    },
    VDataTable: {
      itemsPerPageText: 'Rows per page:',
      density: 'comfortable',
    },
    VDataTableServer: {
      itemsPerPageText: 'Rows per page:',
      density: 'comfortable',
    },
  },
  icons: {
    defaultSet: 'custom',
    aliases,
    sets: {
      custom,
    },
  },
  theme: {
    defaultTheme: 'light',
    themes: {
      light: {
        colors: {
          primary: '#1976D2',
          secondary: '#424242',
          accent: '#8c9eff',
          error: '#7f0000',   // vermelho mais escuro e carregado
        }
      },
      dark: {
        colors: {
          primary: '#1976D2',
          secondary: '#424242',
          accent: '#8c9eff',
          error: '#7f0000',   // vermelho mais escuro e carregado
        }
      },
    },
  },
});
